"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["81581"],{56869(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.codigo_invalido","status":422,"titulo":"C\xf3digo de modalidade fora do formato aceito ou acima de 60 caracteres"},"descricao":{"codigo":"uniplus.selecao.configuracao_cascata_remanejamento.codigo_invalido","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["O c\xf3digo de modalidade de origem ou de destino de uma posi\xe7\xe3o da cascata\\nn\xe3o casa com `^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$` (s\xf3 mai\xfasculas, d\xedgitos e sublinhado) ou excede\\n60 caracteres \u2014 o mesmo vocabul\xe1rio de c\xf3digo de modalidade usado no resto\\ndo m\xf3dulo Sele\xe7\xe3o.","Uma posi\xe7\xe3o da cascata (`modalidadeOrigemCodigo`+`ordem`+`modalidadeDestinoCodigo`)\\npode reprovar este c\xf3digo **at\xe9 duas vezes ao mesmo tempo** \u2014 uma para o\\nc\xf3digo de origem, outra para o de destino, cada uma com o campo (`field`)\\ncorrespondente \u2014 se os dois vierem fora do vocabul\xe1rio. Tamb\xe9m pode\\ncoexistir, no mesmo item, com\\n[`ordem_invalida`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.ordem_invalida):\\nas confer\xeancias do c\xf3digo de origem, do c\xf3digo de destino e da ordem do item s\xe3o independentes entre si e acumulam (ADR-0125).\\nN\xe3o coexiste com\\n[`origem_igual_ao_destino`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.origem_igual_ao_destino)\\nno mesmo par \u2014 essa causa s\xf3 \xe9 conferida quando os dois c\xf3digos do item j\xe1\\ns\xe3o individualmente v\xe1lidos.","Na defini\xe7\xe3o, o lote de erros de item acumula com os de outros itens da\\nmesma lista `destinos`, e, se algum item falhar, tamb\xe9m com as causas que\\nn\xe3o dependem de os itens serem v\xe1lidos (fallback, limites de\\norigens/destinos) \u2014 ver\\n[`campos_obrigatorios`](/erros/uniplus.selecao.configuracao_cascata_remanejamento.campos_obrigatorios)\\npara o detalhe dessa composi\xe7\xe3o."],"comoResolver":["Corrija o c\xf3digo de origem e/ou de destino para casar com\\n`^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$` e ter no m\xe1ximo 60 caracteres \u2014 o mesmo formato usado para\\ndeclarar c\xf3digo de modalidade em qualquer outro corpo do pedido do m\xf3dulo."],"ondeAparece":["Defini\xe7\xe3o de cascata de remanejamento do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao cascata remanejamento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);